            severity: "warning",
            active_poll_id: existingLock.poll_id,
            active_for_ms: now - existingLock.started_at
        }
    }];
}

const pollTimestamp = new Date().toISOString();
const pollId = `${GATEWAY_ID}-${now}`;
flow.set(lockKey, { poll_id: pollId, started_at: now });

const pollPlan = [];
