        blockStartRegister: blockStart,
        blockQuantity: quantity,
        registersPerMeter: REGISTERS_PER_METER,
        floatOrder: FLOAT_ORDER,
        fields: FIELDS,
        meters: blockMeters
    });

    meterIndex += blockSize;
}

msg.gateway_id = GATEWAY_ID;
