/** Convert Modbus node status changes into structured diagnostics. */
const gatewayByNodeId = {
    "mb_get_a18_v2": { id: "A18", ip: "10.40.22.114" },
    "mb_get_a19_v2": { id: "A19", ip: "10.40.22.115" },
    "mb_get_sm3_v2": { id: "SM61-3", ip: "10.40.22.122" }
};

const sourceId = msg.status && msg.status.source ? msg.status.source.id : null;
const gateway = gatewayByNodeId[sourceId] || { id: "unknown", ip: null };

msg.topic = `polipol/4000/energy/modbus/diagnostic/${gateway.id}`;
msg.payload = {
    timestamp: new Date().toISOString(),
    gateway_id: gateway.id,
    gateway_ip: gateway.ip,
    event: "MODBUS_STATUS",
    severity: msg.status && /error|broken|timeout|closed|retry/i.test(msg.status.text || "") ? "warning" : "info",
    status: msg.status || null
};
return msg;

// get errorFlag
const errorFlag = flow.get('errorFlag') || false;

// if errorFlag is True, do nothing and set errorFlag to false
if (errorFlag) {
    flow.set('errorFlag', false)
    return null
} else {
    msg.topic = 'control'
    msg.payload = 'peek'
    return msg
}

// Set the Flow status to the status message of the q-gate
const queueText = flow.get("queueText") || "Queue: 0";
node.status({ fill: "yellow", shape: "ring", text: queueText});

const errorFlag = flow.get("errorFlag") || false;
if (!errorFlag) {
    flow.set("errorFlag", true)
};
msg.delay = 10000;  // 10 seconds between retry
return msg;

// Combine the error message and the queueText

const errorMessage = msg.error.message;
const queueText = flow.get("queueText") || "Queue: 0";
const combinedMessage = `${queueText} - ${errorMessage}`
node.status({ fill: "red", shape: "ring", text: combinedMessage});

// Delete the oldest message on success
// Send a delay message to the trigger which will change the delay settings and restart the trigger
node.send([
    {topic: "control", payload: "drop"},  // Output 1
    {delay: 1000} // Output 2
]);

